ha-card {
  display: flex !important; align-items: center; justify-content: center;
}
ha-markdown {
  width: 240px !important; height: 240px !important; border-radius: 50%;
  margin: auto !important; padding: 0 !important; box-sizing: border-box;
  display: flex !important; align-items: center; justify-content: center;
  text-align: center; font-size: 1.15em; line-height: 1.5;
  background:
    radial-gradient(circle closest-side, var(--ha-card-background, var(--card-background-color)) 70%, transparent 71%),
    conic-gradient({% set ns = namespace(total=0.0, cards=[], rems=[], acc=0.0, out=[]) %}{% for s in states.sensor if s.attributes.get('kind') == 'unused_value' and s.attributes.get('card_status') == 'active' and s.state not in ['unknown', 'unavailable'] and (s.state | float(0)) > 0 %}{% set ns.cards = ns.cards + [[s.state | float(0), s.attributes.get('card_id'), s.attributes.get('color') or 'grey']] %}{% endfor %}{% for s in states.sensor if s.attributes.get('kind') == 'benefit_remaining' and s.attributes.get('card_status') == 'active' and s.state not in ['unknown', 'unavailable'] and (s.state | float(0)) > 0 %}{% set ns.rems = ns.rems + [[s.state | float(0), s.attributes.get('card_id')]] %}{% set ns.total = ns.total + (s.state | float(0)) %}{% endfor %}{% for c in ns.cards | sort(attribute='0', reverse=true) %}{% set parts = ns.rems | selectattr('1', 'eq', c[1]) | sort(attribute='0', reverse=true) | list %}{% set n = parts | count %}{% for p in parts %}{% set pct = p[0] / ns.total * 100 %}{% set mix = (100 - loop.index0 * 55 / ([n - 1, 1] | max)) | round(0) | int %}{% set ns.out = ns.out + ['color-mix(in srgb, var(--' ~ c[2] ~ '-color) ' ~ mix ~ '%, var(--card-background-color)) ' ~ (ns.acc | round(2)) ~ '% ' ~ ((ns.acc + pct) | round(2)) ~ '%'] %}{% set ns.acc = ns.acc + pct %}{% endfor %}{% endfor %}{{ ns.out | join(', ') if ns.out else 'var(--divider-color) 0% 100%' }});
}

